script:
const phanHe = ctx.val('phan_he', 'maintenance').trim().toLowerCase() || 'maintenance';
const targetUrl = `https://tasks.zuizui.io/${phanHe}/create/list`;
const dlg = page.getByRole('dialog');

await step('Mở hộp thoại Thiết lập hiển thị cột', async () => {
  if (!page.url().includes(`/${phanHe}/`)) {
    await page.goto(targetUrl, { waitUntil: 'domcontentloaded' });
  }
  await page.waitForLoadState('networkidle', { timeout: 25000 }).catch(() => {});
  const btn = page.getByTitle('Thiết lập hiển thị cột');
  await btn.waitFor({ timeout: 15000 });
  await btn.click();
  await dlg.waitFor({ timeout: 10000 });
});

await step('Kiểm tra danh sách cột trong dialog và bấm Áp dụng', async () => {
  const expectedCols = ['Mã phiếu', 'Vấn đề', 'Trạng thái', 'Ảnh', 'Đơn vị', 'Người phụ trách', 'SLA tiếp nhận', 'SLA hoàn tất', 'Phân loại phiếu'];
  const dlgText = await dlg.innerText();
  for (const col of expectedCols) {
    assert(dlgText.includes(col), 'Thiếu tùy chọn cột trong dialog: ' + col);
  }
  await dlg.getByText('Áp dụng', { exact: true }).click();
  await dlg.waitFor({ state: 'hidden', timeout: 10000 }).catch(() => {});
});

await step('Kiểm tra tiêu đề cột hiển thị trên bảng danh sách', async () => {
  const headers = page.locator('.maint-col-header');
  const count = await headers.count();
  assert(count >= 4, 'Số lượng cột hiển thị trên bảng quá ít: ' + count);
  const bodyText = await page.locator('#react-app, body').first().innerText();
  for (const h of ['Mã phiếu', 'Vấn đề', 'Trạng thái']) {
    assert(bodyText.includes(h), 'Không thấy tiêu đề cột trên bảng: ' + h);
  }
  ctx.log(`Bảng hiển thị ${count} cột header hợp lệ.`);
});
